const layoutText = String(pdfExtract?.layoutText || "");
// A merged file containing several bank advices must not be assigned using
// the first amount/date. Single advice with supporting pages still works.
const adviceCount = (legacyText.match(/(?:^|\n)\s*(?:DEBIT\s+ADVICE|Payment\s+Advice)\s*(?=\n|$)/gi) || []).length;
if(adviceCount > 1){
    throw new Error("PDF chứa nhiều giấy báo thanh toán. Hãy tách mỗi giấy báo thành một file trước khi tự ghép UNC.");
}
const legacy = extractBulkUncInfo(legacyText);

// The Vietnamese SC layout labels the payee as Party Info, not Name.
const bilingualPayee = firstBulkUncMatch(layoutText,[
    /Beneficiary\s+Party\s+Info\s*\/\s*Th[oô]ng\s+tin\s+đơn\s+vị\s+hưởng[ \t]+([\s\S]{3,300}?)(?=\n\s*Value\s+Date\b)/i
]).replace(/\s+/g," ").trim();
if(bilingualPayee) legacy.beneficiary = bilingualPayee;
const bilingualDatePattern = new RegExp(`(?:^|\\n)Value\\s+Date\\s*/[^\\n0-9]{0,60}\\s*${BULK_UNC_DATE_TOKEN}`,"i");
const labelledDates = [legacyText,layoutText].map(value=>normalizeBulkUncDate(firstBulkUncMatch(value,[bilingualDatePattern]))).filter(Boolean);
if(labelledDates.length){legacy.date = new Set(labelledDates).size === 1 ? labelledDates[0] : "";}
const bilingualReference = firstBulkUncMatch(layoutText,[/Bank\s+Ref\s*\/\s*Số\s+GD\s*:\s*([A-Z0-9]+(?:[ \t]*\/[ \t]*[A-Z0-9]+)?)/i]);
if(bilingualReference) legacy.bankReference = bilingualReference;
legacy.accountNumbers = [...new Set([...legacy.accountNumbers,...visual.accountNumbers])];
